/* Gestor de imagenes: galeria con miniaturas y visor (PNG, JPEG, BMP y GIF) */
#include "z.h"
#define TBH 36
#define TW 132
#define THH 100
typedef struct { char name[200]; u32 *t; int tw, th, done; } im_t;
static zwin *W; static char dir[300], msg[120]; static im_t *L; static int n, cur, mode, top, slide; static u32 *I; static int iw, ih, zoom, ox, oy, drag, dx0, dy0; static u64 slide_t;
static int isimg(const char *s) { return z_ends(s, ".png") || z_ends(s, ".jpg") || z_ends(s, ".jpeg") || z_ends(s, ".bmp") || z_ends(s, ".gif"); }
static int cmp(const void *a, const void *b) { return strcasecmp(((im_t *)a)->name, ((im_t *)b)->name); }
static void scan(void) { for (int i = 0; i < n; i++) free(L[i].t); n = 0; zdirent d; for (int i = 0; n < 1000 && !z_readdir(dir, i, &d); i++) if (!d.is_dir && isimg(d.name)) { memset(&L[n], 0, sizeof L[n]); strncpy0(L[n].name, d.name, 200); n++; } qsort(L, n, sizeof *L, cmp); if (cur >= n) cur = 0; }
static void path(int i, char *o) { snprintf(o, 520, "%s/%s", dir, L[i].name); }
static void open_(int i) { if (i < 0 || i >= n) return; cur = i; free(I); I = 0; char p[520]; path(i, p); int r = z_img_load(p, &I, &iw, &ih); zoom = 0; ox = oy = 0; if (r) { I = 0; snprintf(msg, 120, r == -2 ? _("JPEG progresivo: aún no se puede abrir") : _("No se puede abrir esta imagen")); } else snprintf(msg, 120, "%s  %d x %d", L[i].name, iw, ih); char m[300]; snprintf(m, 300, "[prueba] visor %s: %s %dx%d", p, r ? "FALLO" : "OK", iw, ih); z_log(m); zw_title(W->id, L[i].name); }
static void thumb(int i) { char p[520]; path(i, p); u32 *im; int w, h; L[i].done = 1; if (z_img_load(p, &im, &w, &h)) return; int s = MAX(1, MAX((w + TW - 1) / TW, (h + THH - 1) / THH)); int tw = MAX(1, w / s), th = MAX(1, h / s); if (w <= TW && h <= THH) { tw = w; th = h; s = 1; } L[i].t = malloc(tw * th * 4); for (int y = 0; y < th; y++) for (int x = 0; x < tw; x++) L[i].t[y * tw + x] = im[(y * h / th) * w + x * w / tw]; L[i].tw = tw; L[i].th = th; free(im); }
static const char *BT[] = {"Galería", "<", ">", "Ajustar", "100%", "+", "-", "Girar", "Presentación", "Fondo", "Guardar PNG", "Papelera", "Imprimir"};
static int bx(int i) { int x = 6; for (int k = 0; k < i; k++) x += g_textw(_(BT[k])) + 18; return x; }
/* seleccion rectangular (coordenadas de la imagen): arrastrar selecciona, Mayus+arrastrar mueve la imagen */
static int vx0, vy0; static long vs = 1024; static int sa_x, sa_y, sb_x, sb_y, selecting, sel_on;
static int clampi(int v, int lo, int hi) { return v < lo ? lo : v > hi ? hi : v; }
static int sel_x0(void) { return MIN(sa_x, sb_x); } static int sel_y0(void) { return MIN(sa_y, sb_y); } static int sel_x1(void) { return MAX(sa_x, sb_x); } static int sel_y1(void) { return MAX(sa_y, sb_y); }
static int has_sel(void) { return sel_on && I && sel_x1() - sel_x0() > 1 && sel_y1() - sel_y0() > 1; }
static void to_img(int wx, int wy, int *x, int *y) { *x = clampi((int)((long)(wx - vx0) * 1024 / vs), 0, iw); *y = clampi((int)((long)(wy - vy0) * 1024 / vs), 0, ih); }
static u32 *crop(int *w, int *h) { int x0 = sel_x0(), y0 = sel_y0(); *w = sel_x1() - x0; *h = sel_y1() - y0; u32 *o = malloc((long)*w * *h * 4); for (int y = 0; y < *h; y++) memcpy(o + (long)y * *w, I + (long)(y0 + y) * iw + x0, *w * 4); return o; }
static void draw(void); static void act(int b);
static void img_menu(int x, int y) { int sx, sy; zw_screen(W, x, y, &sx, &sy); char m[160];
    if (has_sel()) { static const char *it[] = {"Copiar la selección", "Guardar la selección como PNG", "Imprimir la selección", "Quitar la selección"}; int r = ui_menu(sx, sy, it, 4); int w, h; if (r < 0) return; if (r == 3) { sel_on = 0; return; } u32 *c = crop(&w, &h);
        if (r == 0) { int e = z_clip_set_img(c, w, h); snprintf(msg, 120, "%s", e ? z_errstr(e) : _("Selección copiada")); snprintf(m, 160, "[prueba] visor copio seleccion %dx%d: %d", w, h, e); z_log(m); }
        else if (r == 1) { char p[520]; path(cur, p); char *dt = strrchr(p, '.'); if (dt) *dt = 0; strcat(p, "-recorte.png"); int e = z_png_save(p, c, w, h); z_sync(); snprintf(msg, 120, "%s", e ? z_errstr(e) : _("Recorte guardado")); snprintf(m, 160, "[prueba] visor recorte %dx%d: %d", w, h, e); z_log(m); scan(); }
        else if (r == 2) zp_print_image(L[cur].name, c, w, h); free(c); }
    else { static const char *it[] = {"Copiar la imagen", "Imprimir", "Poner como fondo"}; int r = ui_menu(sx, sy, it, 3); if (r == 0 && I) { int e = z_clip_set_img(I, iw, ih); snprintf(msg, 120, "%s", e ? z_errstr(e) : _("Imagen copiada")); } else if (r == 1) act(12); else if (r == 2) act(9); } }
static void draw(void) { g_clear(W, 0x1F2937); g_rect(W, 0, 0, W->w, TBH, UI_PANEL); for (int i = 0; i < 13; i++) { ui_button(W, bx(i), 5, g_textw(_(BT[i])) + 14, 26, BT[i], (i == 0 && mode == 0) || (i == 8 && slide) ? 2 : 0); } int H = W->h - TBH - 22;
    if (mode == 0) { int cols = MAX(1, W->w / (TW + 16)), vis = H / (THH + 34) + 1; for (int i = top * cols; i < n && i < (top + vis) * cols; i++) { int c = i % cols, r = i / cols - top, x = 8 + c * (TW + 16), y = TBH + 8 + r * (THH + 34); if (i == cur) g_round(W, x - 4, y - 4, TW + 8, THH + 30, 4, UI_ACC); if (L[i].t) g_image(W, x + (TW - L[i].tw) / 2, y + (THH - L[i].th) / 2, L[i].tw, L[i].th, L[i].t); else g_rect(W, x, y, TW, THH, 0x374151); zw_clip(W, x, y + THH + 4, TW, 18); g_text(W, x, y + THH + 6, L[i].name, 0xE5E7EB); zw_noclip(W); } if (!n) g_text(W, 20, TBH + 20, _("No hay imágenes en esta carpeta."), 0xE5E7EB); }
    else if (I) { long s = zoom ? zoom * 1024LL / 100 : MIN(MIN(W->w * 1024LL / iw, H * 1024LL / ih), 4096LL); int dw = iw * s / 1024, dh = ih * s / 1024, x0 = (W->w - dw) / 2 + ox, y0 = TBH + (H - dh) / 2 + oy; vx0 = x0; vy0 = y0; vs = s; for (int y = MAX(TBH, y0); y < MIN(TBH + H, y0 + dh); y++) { u32 *o = W->px + y * W->w, *r = I + (long)(y - y0) * 1024 / s * iw; for (int x = MAX(0, x0); x < MIN(W->w, x0 + dw); x++) { long sx = (long)(x - x0) * 1024 / s; o[x] = r[sx < iw ? sx : iw - 1]; } }
        if (has_sel()) { int a = x0 + sel_x0() * s / 1024, b = y0 + sel_y0() * s / 1024, c = x0 + sel_x1() * s / 1024, d = y0 + sel_y1() * s / 1024; for (int k = a; k < c; k += 6) { g_rect(W, k, b, 3, 1, 0xFFFFFF); g_rect(W, k, d, 3, 1, 0xFFFFFF); g_rect(W, k + 3, b, 3, 1, 0); g_rect(W, k + 3, d, 3, 1, 0); } for (int k = b; k < d; k += 6) { g_rect(W, a, k, 1, 3, 0xFFFFFF); g_rect(W, c, k, 1, 3, 0xFFFFFF); g_rect(W, a, k + 3, 1, 3, 0); g_rect(W, c, k + 3, 1, 3, 0); } } }
    g_rect(W, 0, W->h - 22, W->w, 22, UI_PANEL); char b[400]; snprintf(b, 400, "%s   %d %s   %s", dir, n, _("imágenes"), msg); g_text(W, 8, W->h - 19, b, UI_TEXT); zw_present(W); }
static void pbuild(zpdoc *d, const zpset *s, void *c) { double m = 36, pw = zp_pw(d) - 2 * m, ph = zp_ph(d) - 2 * m - 20; zp_page(d); if (!I) return; double k = MIN(pw / iw, ph / ih); double w = iw * k, h = ih * k; zp_image(d, m + (pw - w) / 2, m + (ph - h) / 2, w, h, I, iw, ih); zp_text(d, m, zp_ph(d) - m, ZPF_SANS, 9, 0x6B7280, L[cur].name); }
static void rot(void) { if (!I) return; u32 *o = malloc(iw * ih * 4); for (int y = 0; y < ih; y++) for (int x = 0; x < iw; x++) o[x * ih + (ih - 1 - y)] = I[y * iw + x]; free(I); I = o; int t = iw; iw = ih; ih = t; }
static void act(int b) { char p[520]; switch (b) { case 0: mode = !mode; if (mode) open_(cur); break; case 1: if (n) { mode = 1; open_((cur + n - 1) % n); } break; case 2: if (n) { mode = 1; open_((cur + 1) % n); } break; case 3: zoom = 0; ox = oy = 0; break; case 4: zoom = 100; ox = oy = 0; break; case 5: zoom = MIN((zoom ? zoom : 100) * 5 / 4, 800); break; case 6: zoom = MAX((zoom ? zoom : 100) * 4 / 5, 10); break; case 7: rot(); break; case 8: slide = !slide; slide_t = z_ms(); if (slide && !mode) { mode = 1; open_(cur); } break; case 9: if (n) { path(cur, p); z_cfg_sets("fondo", p); z_notify(); strcpy(msg, _("Puesta como fondo")); z_log("[prueba] fondo cambiado"); } break; case 10: if (I) { u8 *o; long len; z_png_encode(I, iw, ih, &o, &len); path(cur, p); char *d = strrchr(p, '.'); if (d) *d = 0; strcat(p, "-copia.png"); int e = z_writefile(p, o, len); free(o); snprintf(msg, 120, e ? "%s" : "%s", e ? z_errstr(e) : _("Guardada como PNG")); char m[60]; snprintf(m, 60, "[prueba] visor guardo png: %s", e ? "error" : "OK"); z_log(m); scan(); } break; case 12: if (n) { if (!I || !mode) open_(cur); if (I) { zp_default_land = iw > ih; zp_dialog(L[cur].name, pbuild, 0); } } break; case 11: if (n && ui_confirm("Papelera", "¿Mover esta imagen a la papelera?")) { path(cur, p); int e = z_trash(p); snprintf(msg, 120, "%s", e ? z_errstr(e) : _("Movida a la papelera")); scan(); if (mode && n) open_(MIN(cur, n - 1)); } break; } }
int main(const char *a) { L = calloc(1000, sizeof *L); zsys s; z_sysinfo(&s); W = zw_new("Imágenes", -1, 0, MIN(900, (int)s.scr_w - 40), MIN(600, (int)s.scr_h - 90), WF_DECOR | WF_RESIZE); char want[200] = ""; if (a[0]) { strncpy0(dir, a, 300); zdirent d; if (!z_stat(a, &d) && !d.is_dir) { char *sl = strrchr(dir, '/'); strncpy0(want, sl + 1, 200); *sl = 0; } } else { zdirent d; strcpy(dir, z_stat("/sys", &d) ? "/rd/res" : "/sys"); } scan(); for (int i = 0; i < n; i++) if (!strcmp(L[i].name, want)) { cur = i; mode = 1; open_(i); } if (!a[0] && !n) { strcpy(dir, "/rd/res"); scan(); } { char m[360]; snprintf(m, 360, "[prueba] visor %s: galeria %d", dir, n); z_log(m); } draw(); zevent e;
    for (;;) { int pend = -1; if (mode == 0) for (int i = 0; i < n; i++) if (!L[i].done) { pend = i; break; } int g = z_event(&e, pend >= 0 ? 0 : slide ? 200 : -1); if (!g) { if (pend >= 0) { thumb(pend); draw(); } if (slide && mode && z_ms() - slide_t > 4000) { slide_t = z_ms(); act(2); draw(); } continue; } if (e.type == EV_REDRAW) { draw(); continue; } if (e.win != (u32)W->id) continue; if (e.type == EV_CLOSE) return 0; if (e.type == EV_RESIZE) { zw_resized(W, e.x, e.y); draw(); continue; }
        if (e.type == EV_DOWN) { if (e.y < TBH) { for (int i = 12; i >= 0; i--) if (e.x >= bx(i)) { if (e.x < bx(i) + g_textw(_(BT[i])) + 14) act(i); break; } } else if (mode == 0) { int cols = MAX(1, W->w / (TW + 16)), c = (e.x - 8) / (TW + 16), r = (e.y - TBH - 8) / (THH + 34) + top, i = r * cols + c; if (c < cols && i < n) { if (i == cur || (e.btn & 2)) { mode = 1; open_(i); } else cur = i; } } else if (e.btn & 2) { img_menu(e.x, e.y); } else if (e.mods & M_SHIFT || (e.btn & 4)) { drag = 1; dx0 = e.x - ox; dy0 = e.y - oy; } else if (I) { selecting = 1; sel_on = 1; to_img(e.x, e.y, &sa_x, &sa_y); sb_x = sa_x; sb_y = sa_y; } }
        else if (e.type == EV_MOVE && drag) { ox = e.x - dx0; oy = e.y - dy0; } else if (e.type == EV_MOVE && selecting) { to_img(e.x, e.y, &sb_x, &sb_y); } else if (e.type == EV_UP) { drag = 0; if (selecting) { selecting = 0; if (!has_sel()) sel_on = 0; else { char m[100]; snprintf(m, 100, "[prueba] visor seleccion %dx%d", sel_x1() - sel_x0(), sel_y1() - sel_y0()); z_log(m); } } } else if (e.type == EV_WHEEL) { if (mode) zoom = e.key > 0 ? MIN((zoom ? zoom : 100) * 5 / 4, 800) : MAX((zoom ? zoom : 100) * 4 / 5, 10); else top = MAX(0, top - (int)e.key); }
        else if (e.type == EV_KEY) { if (e.key == K_RIGHT || e.ch == ' ') act(2); else if (e.key == K_LEFT) act(1); else if (e.ch == 27) { mode = 0; slide = 0; } else if (e.ch == '\n') act(0); else if (e.ch == 'r' || e.ch == 'R') act(7); else if (e.ch == '+') act(5); else if (e.ch == '-') act(6); else if (e.key == K_DEL) act(11); else if (e.ch == 16) act(12); else continue; } else continue; draw(); }
}
